SELECT AVG(pc.procedure_count) AS average_procedures FROM (SELECT p.subject_id, COUNT(DISTINCT pr.procedure_code) AS procedure_count FROM physionet-data.mimiciv_3_1_hosp.patients p JOIN physionet-data.mimiciv_3_1_hosp.admissions a ON p.subject_id = a.subject_id JOIN physionet-data.mimiciv_3_1_hosp.procedures_icd pr ON a.hadm_id = pr.subject_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) = 47 AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2015 AND 2016 AND pr.icd_code IN ('47005', '47006') GROUP BY p.subject_id) AS pc;